import { Icon, Pin, PinFilled } from 'components/icon';

export const BigNumberPin = ({ pinned }: { pinned: boolean }) => {
  return pinned ? (
    <Icon
      data-testid="pin-filled"
      icon={PinFilled}
      size="medium"
      style={{ margin: 'auto 0' }}
    />
  ) : (
    <Icon
      data-testid="pin"
      icon={Pin}
      size="medium"
      style={{ margin: 'auto 0' }}
    />
  );
};
